fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    // Handle empty array early to avoid modulo-by-zero
    if n == 0 {
        return a;
    }
    // Reduce the offset modulo n
    let k = offset % n;
    // In-place rotate_left is O(n) and works on slices
    let mut b = a;
    b.rotate_left(k);
    b
}

